<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,watch} from 'vue';
import {useSession} from './store';
import PathNodeEditor from './PathNodeEditor.vue';
import {moveNode,mapPiece,piecePath} from '../../../packages/pattern/edit';
type Point={xMm:number;yMm:number};
const props=defineProps<{language:'zh'|'en';selection?:{markingId:string;pieceId:string}}>(),emit=defineEmits<{select:[id:string]}>(),store=useSession(),advanced=inject('advancedMode',ref(false)),markingId=ref(''),pieceId=ref(''),rings=ref<Point[][]>([]),ringIndex=ref(0),nodeIndex=ref(0),zh=computed(()=>props.language==='zh'),message=ref(''),editorVersion=ref(0);
const marking=computed(()=>store.data.project?.markings?.find(m=>m.id===markingId.value)),path=computed(()=>marking.value?.paths.find(p=>p.pieceId===pieceId.value)),point=computed(()=>rings.value[ringIndex.value]?.[nodeIndex.value]),piece=computed(()=>store.data.project?.pieces.find(p=>p.id===pieceId.value)),background=computed(()=>piece.value?[piece.value.nodes,...(piece.value.holes??[])]:[]);
const availablePaths=computed(()=>(marking.value?.paths??[]).filter(path=>store.data.project?.pieces.some(piece=>piece.id===path.pieceId)));
watch([marking,availablePaths],()=>{if(!availablePaths.value.some(path=>path.pieceId===pieceId.value))pieceId.value=availablePaths.value[0]?.pieceId??'';});
watch(()=>props.selection,s=>{if(s){markingId.value=s.markingId;pieceId.value=s.pieceId;}},{immediate:true});
function reset(){rings.value=JSON.parse(JSON.stringify(path.value?.rings??[]));ringIndex.value=0;nodeIndex.value=0;message.value='';editorVersion.value++;}
watch(()=>JSON.stringify([markingId.value,path.value]),reset,{immediate:true});
function explain(code:string){return ({MARKING_OUTSIDE_PATCH:zh.value?'节点超出当前裁片，请调整后再确认。':localize('A node is outside this pattern. Adjust it before confirming.'),MARKING_SEAM_CHANGE:zh.value?'本次修改改变了接缝交点，请改为编辑源区域。':localize('This changes a seam crossing. Edit the source region instead.'),MARKING_LOCKED:zh.value?'花纹已锁定。':localize('The marking is locked.'),STALE_MARKING:zh.value?'模型或裁片已改变，请先重新展开。':localize('The model or pattern changed. Recompute unwrapping first.'),INVALID_GEOMETRY:zh.value?'轮廓无效或自相交，请调整节点。':localize('The contour is invalid or intersects itself. Adjust its nodes.')} as Record<string,string>)[code]??(zh.value?'无法保存，请检查花纹与轮廓。':localize('Could not save. Review the marking and contour.'));}
async function save(){const p=store.data.project;if(!p||!path.value)return;const saved=await store.run(()=>window.fpcad.editMarking(p.id,p.revision,markingId.value,pieceId.value,JSON.parse(JSON.stringify(rings.value))));message.value=saved?(zh.value?'花纹编辑已保存。':localize('Marking edit saved.')):explain(store.error);}
const source=computed(()=>(store.data.project?.pieces.find(p=>p.id===marking.value?.sourcePieceId)??store.data.project?.patternLibrary?.find(r=>r.piece.id===marking.value?.sourcePieceId)?.piece)),sourceNodeId=ref(''),sourceX=ref(0),sourceY=ref(0),replaceManual=ref(false),sourceNodes=computed(()=>[...(source.value?.nodes??[]),...(source.value?.holes??[]).flat()]),sourcePoint=computed(()=>sourceNodes.value.find(n=>n.id===sourceNodeId.value)),sourceDraft=computed(()=>source.value?moveNode(source.value,sourceNodeId.value,sourceX.value,sourceY.value):undefined),sourceRings=computed(()=>sourceDraft.value?[sourceDraft.value.nodes,...(sourceDraft.value.holes??[])]:[]),sourceMessage=ref(''),sourceVersion=ref(0),manualNeeded=computed(()=>store.data.project?.markings?.some(m=>m.sourcePieceId===source.value?.id&&(m.editMode==='uv-manual'||m.source==='manual'&&!m.editMode))??false);
function resetSource(){sourceNodeId.value=source.value?.nodes[0]?.id??'';sourceX.value=sourcePoint.value?.xMm??0;sourceY.value=sourcePoint.value?.yMm??0;replaceManual.value=false;sourceMessage.value='';sourceVersion.value++;}
watch(()=>JSON.stringify(source.value),resetSource,{immediate:true});
function selectSource(r:number,n:number){const node=[source.value?.nodes??[],...(source.value?.holes??[])][r]?.[n];if(!node||node.id===sourceNodeId.value)return;sourceNodeId.value=node.id;sourceX.value=node.xMm;sourceY.value=node.yMm;}
function updateSource(rings:Point[][]){const original=[source.value?.nodes??[],...(source.value?.holes??[])];for(let r=0;r<original.length;r++)for(let n=0;n<original[r].length;n++)if(original[r][n].id===sourceNodeId.value){sourceX.value=rings[r][n].xMm;sourceY.value=rings[r][n].yMm;}}
async function saveSource(){const p=store.data.project,s=source.value,n=sourcePoint.value;if(!p||!s||!n)return;const saved=await store.run(()=>window.fpcad.editMarkingSource(p.id,p.revision,s.id,n.id,sourceX.value,sourceY.value,replaceManual.value));sourceMessage.value=saved?(zh.value?'源节点已保存，所有花纹已同步。':localize('Source node saved; all markings updated.')):explain(store.error);}
const sourcePath=computed(()=>sourceDraft.value?piecePath(mapPiece(sourceDraft.value,p=>({xMm:p.xMm,yMm:-p.yMm}))):''),patternPath=computed(()=>piece.value?piecePath(mapPiece(piece.value,p=>({xMm:p.xMm,yMm:-p.yMm}))):''),sourceCurveBounds=computed(()=>source.value?.curves?.flatMap(c=>[c.c1,c.c2])??[]);
function selectPiece(){emit('select',pieceId.value);}
</script>
<template><section v-if="store.data.project?.markings?.length" class="marking-editor"><strong>{{zh?'花纹路径编辑':localize('Edit marking paths')}}</strong><p>{{zh?'直接点击和拖动轮廓或孔洞圆点。修改暂存，确认后逆映射到模型；跨接缝修改请编辑源区域。':localize('Select and drag contour or hole nodes. Confirm the draft to inverse-map it onto the model. Edit the source region for seam changes.')}}</p><div class="marking-choices"><select v-model="markingId" :aria-label="zh?'选择花纹':localize('Select marking')"><option value="">{{zh?'选择花纹':localize('Select marking')}}</option><option v-for="m in store.data.project?.markings" :key="m.id" :value="m.id">{{m.name}}</option></select><select v-if="availablePaths.length" v-model="pieceId" :aria-label="zh?'选择纸样':localize('Select pattern')" @change="selectPiece"><option value="">{{zh?'选择纸样':localize('Select pattern')}}</option><option v-for="p in availablePaths" :key="p.pieceId" :value="p.pieceId">{{store.data.project?.pieces.find(v=>v.id===p.pieceId)?.name}}</option></select></div><p v-if="marking&&!availablePaths.length" class="uncut-marking-note" role="status">{{zh?'尚未裁切，没有可编辑纸样。请在模型工具栏编辑已贴附花纹节点或继续下方源区域编辑；完成贴附后进入「裁切版型」生成纸样。':localize('No cutting patterns yet. Edit attached nodes in the model toolbar or edit the source region below. Finish placement, then generate patterns in Cutting.')}}</p><template v-if="path&&piece"><PathNodeEditor :key="editorVersion" :context="markingId+pieceId" :rings="rings" :background="background" :background-path="patternPath" :color="marking?.color" :language="language" :disabled="store.busy||marking?.locked" @update="rings=$event" @cancel="reset" @select="(r,n)=>{ringIndex=r;nodeIndex=n}"/><details v-if="advanced&&point"><summary>{{zh?'选中节点坐标':localize('Selected node coordinates')}}</summary><label>X mm<input v-model.number="point.xMm" type="number" step=".1" :disabled="store.busy||marking?.locked"></label><label>Y mm<input v-model.number="point.yMm" type="number" step=".1" :disabled="store.busy||marking?.locked"></label></details><div class="editor-actions"><button :disabled="store.busy||marking?.locked" @click="save">{{zh?'校验并逆映射保存':localize('Validate, inverse-map and save')}}</button><button :disabled="store.busy" @click="reset">{{zh?'取消花纹修改':localize('Cancel marking edits')}}</button></div><p v-if="message" role="status">{{message}}</p></template><section v-if="source" class="source-marking-editor"><strong>{{zh?'源区域节点与跨缝协调编辑':localize('Source region nodes and coordinated seam edits')}}</strong><p>{{zh?'在源轮廓上选择并拖动一个节点，确认后重投影所有相关花纹。选另一个节点会取消当前节点的草稿。':localize('Select and drag a source node, then confirm to reproject all related markings. Selecting another node discards the current node draft.')}}</p><button @click="emit('select',source.id)">{{zh?'查看源区域':localize('View source region')}}</button><PathNodeEditor :key="sourceVersion" :context="source.id" :rings="sourceRings" :shape-path="sourcePath" :extra-bounds="sourceCurveBounds" :language="language" :color="marking?.color" :disabled="store.busy||marking?.locked" :topology="false" @select="selectSource" @update="updateSource" @cancel="resetSource"/><details v-if="advanced&&sourcePoint"><summary>{{zh?'选中源节点坐标':localize('Selected source node coordinates')}}</summary><label>X mm<input v-model.number="sourceX" type="number" step=".1" :disabled="store.busy||marking?.locked"></label><label>Y mm<input v-model.number="sourceY" type="number" step=".1" :disabled="store.busy||marking?.locked"></label></details><label v-if="manualNeeded"><input v-model="replaceManual" type="checkbox">{{zh?'确认替换该源的片内人工花纹编辑':localize('Confirm replacement of manual UV edits for this source')}}</label><div class="editor-actions"><button :disabled="store.busy||marking?.locked||!sourcePoint||(manualNeeded&&!replaceManual)" @click="saveSource">{{zh?'协调重投影并整体保存':localize('Reproject together and save atomically')}}</button><button :disabled="store.busy" @click="resetSource">{{zh?'取消源节点修改':localize('Cancel source node edits')}}</button></div><p v-if="sourceMessage" role="status">{{sourceMessage}}</p></section></section></template>
<style scoped>.marking-editor{padding-top:14px}.marking-choices,.editor-actions{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}.marking-editor label{display:inline-block;margin:6px}.marking-editor input{width:100px}.marking-editor input[type=checkbox]{width:auto}.marking-editor select{max-width:240px}.marking-editor p{line-height:1.5}.source-marking-editor{border-top:1px solid var(--border);margin-top:15px;padding-top:10px}</style>
